async def test_api_activity_feed_channel_on_new_entry_delivers_contract_valid_payloads(rig):
    client, socket = rig
    await client.register_scenario(
        {
            "topic": "api:activity_feed:agent:test-id",
            "onJoin": [
                {"type": "autoReply"},
                {"type": "autoPush", "event": "new_entry"},
            ],
        }
    )
    channel = await ApiActivityFeedChannel.join_agent(socket, "test-id")
    future: asyncio.Future = asyncio.get_event_loop().create_future()

    def handler(payload):
        if not future.done():
            future.set_result(payload)

    channel.on_new_entry(handler)
    payload = await asyncio.wait_for(future, timeout=1.0)
    assert payload is not None


